return $input.all().map(item => {
  const data = item.json;
  const config = data.config;

  const temperature = data.temperature;
  const humidity = data.humidity;

  // Chặn dữ liệu thiếu hoặc không hợp lệ trước khi xét cảnh báo.
  if (
    !data.room_id ||
    !Number.isFinite(temperature) ||
    temperature < -40 || temperature > 80 ||
    !Number.isFinite(humidity) ||
    humidity < 0 ||
    humidity > 100
  ) {
    return {
      json: {
        ...data,
        severity: "INVALID",
        alert_type: "INVALID_TELEMETRY",
        message: "Dữ liệu cảm biến không hợp lệ",
        request_buzzer: false
      }
    };
  }

  let tempLevel = 0;
  if (temperature >= config.temperature_critical) {
    tempLevel = 2;
  } else if (temperature >= config.temperature_warning) {
    tempLevel = 1;
  }

  let humidityLevel = 0;
  if (
    humidity <= config.humidity_low_critical ||
    humidity >= config.humidity_high_critical
  ) {
    humidityLevel = 2;
  } else if (
    humidity <= config.humidity_low_warning ||
    humidity >= config.humidity_high_warning
  ) {
    humidityLevel = 1;
  }

  // Nếu cả hai chỉ số cùng bất thường, lấy mức nặng hơn.
  const level = Math.max(tempLevel, humidityLevel);
  const severity = ["NORMAL", "WARNING", "CRITICAL"][level];

  let alertType = "NONE";
  if (tempLevel > 0 && humidityLevel > 0) {
    alertType = "TEMPERATURE_AND_HUMIDITY";
  } else if (tempLevel > 0) {
    alertType = "TEMPERATURE";
  } else if (humidityLevel > 0) {
    alertType = "HUMIDITY";
  }

  return {
    json: {
      ...data,
      severity,
      alert_type: alertType,
      message: `Phòng ${data.room_id}: ${temperature}°C, độ ẩm ${humidity}% - ${severity}`,
      request_buzzer: severity === "CRITICAL"
    }
  };
});

return $input.all().map(item => {
  const data = item.json;
  const critical = data.severity === "CRITICAL";
  const leftCritical =
    data.previous_severity === "CRITICAL" && !critical;

  return {
    json: {
      room: data.room_id,
      room_id: data.room_id,
      device_id: data.device_id,
      timestamp: data.timestamp,
      severity: data.severity,
      alert_type: data.alert_type,
      previous_severity: data.previous_severity,
      message: data.message,

      wf07_status: "ALERT",
      should_notify: true,
      email_request: {
        subject: `[${data.severity}] Phòng ${data.room_id} - Cảnh báo môi trường`,
        body:
          `Phòng: ${data.room_id}\n` +
          `Thời gian: ${data.timestamp}\n` +
          `Nhiệt độ: ${data.temperature}°C\n` +
          `Độ ẩm: ${data.humidity}%\n` +
          `Mức: ${data.severity}\n` +
          `Nội dung: ${data.message}`
      },

      incident_request: critical
        ? {
            type: "ENVIRONMENT",
            severity: "CRITICAL",
            room_id: data.room_id,
            source: "WF07_ENV_ALERT",
            message: data.message
          }
        : null,

      device_request: critical
        ? {
            buzzer: "ON",
            reason: "ENVIRONMENT_CRITICAL"
          }
        : null,

      // Báo rằng nguyên nhân môi trường không còn cần giữ còi.
      environment_buzzer_release: leftCritical,

      incident_resolution_request: leftCritical
        ? {
            type: "ENVIRONMENT",
            room_id: data.room_id,
            source: "WF07_ENV_ALERT",
            reason: "ENVIRONMENT_BELOW_CRITICAL"
          }
        : null
    }
  };
});

// Dữ liệu cảm biến mới, lấy từ node phân loại.
const current = $('Phan loai canh bao').first().json;

// Dòng trạng thái cũ trong Data Table.
// Khi chưa có dòng nào, Always Output Data có thể cho ra {}.
const saved = $input.first()?.json ?? {};
const hasSavedState = saved.room_id === current.room_id;

let shouldNotify = false;
let shouldUpdateState = false;
let reason = "";

if (current.severity === "INVALID") {
  reason = "Dữ liệu lỗi, không dùng để thay đổi trạng thái cảnh báo";
} else if (current.severity === "NORMAL") {
  shouldUpdateState =
    !hasSavedState || saved.severity !== "NORMAL";
  reason = "Phòng bình thường; đặt lại trạng thái cảnh báo";
} else {
  const isNewAlert =
    !hasSavedState ||
    saved.severity !== current.severity ||
    saved.alert_type !== current.alert_type;

  shouldNotify = isNewAlert;
  shouldUpdateState = isNewAlert;
  reason = isNewAlert
    ? "Mức hoặc loại cảnh báo đã thay đổi"
    : "Cảnh báo này đã được ghi nhận, bỏ qua bản tin lặp";
}

return [{
  json: {
    ...current,
    previous_severity: hasSavedState ? saved.severity : null,
    previous_alert_type: hasSavedState ? saved.alert_type : null,
    should_notify: shouldNotify,
    should_update_state: shouldUpdateState,
    dedupe_reason: reason,
    state_to_save: {
      room_id: current.room_id,
      severity: current.severity,
      alert_type: current.alert_type,
      last_notified_at: shouldNotify
        ? new Date().toISOString()
        : (saved.last_notified_at ?? "")
    }
  }
}];

return [{
  json: $('Quyet dinh canh bao moi').first().json
}];

return $input.all().map(item => {
  const data = item.json;
  const leftCritical = data.previous_severity === "CRITICAL";

  return {
    json: {
      room: data.room_id,
      room_id: data.room_id,
      device_id: data.device_id,
      timestamp: data.timestamp,
      event: data.previous_severity ? "ENVIRONMENT_RECOVERED" : "ENVIRONMENT_INITIALIZED",
      wf07_status: data.previous_severity ? "RECOVERED" : "INITIALIZED",
      should_notify: false,
      severity: "NORMAL",
      previous_severity: data.previous_severity,
      message: `Phòng ${data.room_id}: nhiệt độ và độ ẩm ở mức bình thường`,

      // Chỉ cần giải phóng còi và đóng incident nếu trước đó là CRITICAL.
      environment_buzzer_release: leftCritical,
      incident_resolution_request: leftCritical
        ? {
            type: "ENVIRONMENT",
            room_id: data.room_id,
            source: "WF07_ENV_ALERT",
            reason: "ENVIRONMENT_RECOVERED"
          }
        : null
    }
  };
});

// WF07 accepts ONE sensor record per execution.
const items = $input.all();
if (items.length !== 1) throw new Error('WF07 requires exactly one telemetry item per execution');
const data = items[0].json;
const room = data.room ?? data.room_id;
if (typeof room !== 'string' || !room.trim()) throw new Error('Telemetry missing room');
if (typeof data.device_id !== 'string' || !data.device_id.trim()) throw new Error('Telemetry missing device_id');
return [{json: {...data, room: room.trim(), room_id: room.trim(),
 timestamp: data.timestamp ?? new Date().toISOString(),
 backend_base_url: 'http://host.docker.internal:3001/api'}}];

const telemetry = $('Telemetry dau vao').first().json;
const row = $input.first()?.json ?? {};

if (row.room_id !== telemetry.room_id) {
  throw new Error(
    `Không tìm thấy Config cho phòng ${telemetry.room_id}`
  );
}

const fields = [
  "temperature_warning",
  "temperature_critical",
  "humidity_low_warning",
  "humidity_low_critical",
  "humidity_high_warning",
  "humidity_high_critical"
];

const config = {};

for (const field of fields) {
  const raw = row[field];

  if (
    raw === undefined ||
    raw === null ||
    String(raw).trim() === ""
  ) {
    throw new Error(`Config thiếu cột hoặc giá trị: ${field}`);
  }

  const value = Number(raw);
  if (!Number.isFinite(value)) {
    throw new Error(`Config ${field} không phải số: ${raw}`);
  }

  config[field] = value;
}

if (
  config.temperature_warning >= config.temperature_critical ||
  config.humidity_low_critical >= config.humidity_low_warning ||
  config.humidity_low_warning >= config.humidity_high_warning ||
  config.humidity_high_warning >= config.humidity_high_critical
) {
  throw new Error("Thứ tự các ngưỡng trong Config không hợp lệ");
}

return [{
  json: {
    ...telemetry,
    config
  }
}];

const severity = $('Phan loai canh bao').first().json.severity;

const result = severity === 'NORMAL'
  ? $('Tao yeu cau phuc hoi').first().json
  : $('Tao yeu cau canh bao').first().json;

return [{ json: result }];

const d = $('Quyet dinh canh bao moi').first().json;
return [{json: {
 room: d.room_id, room_id: d.room_id, device_id: d.device_id,
 timestamp: d.timestamp, severity: d.severity, alert_type: d.alert_type,
 wf07_status: d.severity === 'INVALID' ? 'INVALID' : 'NO_CHANGE',
 should_notify: false, message: d.message,
 incident_request: null, device_request: null,
 environment_buzzer_release: false, incident_resolution_request: null
}}];
